    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut ks: Vec<int> = []
    let mut vs: Vec<int> = []
    let mut cap = 1
    let mut first = true
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 { continue }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let mut i = 0
            let n: int = ks.len() as int
            while i < n {
                if ks[i as usize] == k {
                    ks.remove(i as usize)
                    vs.remove(i as usize)
                    break
                }
                i += 1
            }
            ks.push(k)
            vs.push(v)
            if (ks.len() as int) > cap {
                let e = ks[0]
                ks.remove(0)
                vs.remove(0)
                println("evict ${e}")
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let mut found = -1
            let mut i = 0
            let n: int = ks.len() as int
            while i < n {
                if ks[i as usize] == k {
                    found = vs[i as usize]
                    ks.remove(i as usize)
                    vs.remove(i as usize)
                    ks.push(k)
                    vs.push(found)
                    break
                }
                i += 1
            }
            println("${found}")
        } else if cmd == "keys" {
            if ks.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let mut i: int = (ks.len() as int) - 1
                while i >= 0 {
                    if out != "" { out = out + " " }
                    out = out + "${ks[i as usize]}"
                    i -= 1
                }
                println("${out}")
            }
        }
    }
}

